 static object Respond(JsonElement input){string path=Path.GetFullPath(input.GetProperty("path").GetString());var tree=Trees[path];var compilation=Compilation;if(input.TryGetProperty("source",out var text)){var replacement=CSharpSyntaxTree.ParseText(text.GetString(),path:path);compilation=compilation.ReplaceSyntaxTree(tree,replacement);tree=replacement;}var sem=compilation.GetSemanticModel(tree);string wanted=input.TryGetProperty("method_id",out var mi)?mi.GetString():null;var output=new List<object>();foreach(var node in tree.GetRoot().DescendantNodes().Where(n=>n is BaseMethodDeclarationSyntax||n is AccessorDeclarationSyntax)){var symbol=sem.GetDeclaredSymbol(node) as IMethodSymbol;if(symbol==null||wanted!=null&&Method(symbol)!=wanted)continue;BlockSyntax body=node is BaseMethodDeclarationSyntax m?m.Body:((AccessorDeclarationSyntax)node).Body;output.Add(new Model(sem,node,body,symbol).Run());}return new{methods=output,source_only=true,candidate_compiled=false};}
 public static void Main(string[]args){var manifest=JsonDocument.Parse(File.ReadAllText(args[0])).RootElement;foreach(var item in manifest.GetProperty("sources").EnumerateArray()){string logical=item.GetProperty("path").GetString();string physical=item.TryGetProperty("input_path",out var p)?p.GetString():logical;string path=Path.GetFullPath(logical);Trees[path]=CSharpSyntaxTree.ParseText(File.ReadAllText(physical),path:path);}var refs=manifest.GetProperty("references").EnumerateArray().Select(x=>MetadataReference.CreateFromFile(x.GetProperty("path").GetString()));Compilation=CSharpCompilation.Create("IndependentAstControl",Trees.Values,refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary,assemblyIdentityComparer:DesktopAssemblyIdentityComparer.Default));string line;while((line=Console.ReadLine())!=null){try{using(var input=JsonDocument.Parse(line))Console.WriteLine(JsonSerializer.Serialize(Respond(input.RootElement),new JsonSerializerOptions{MaxDepth=2048}));}catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{error=e.GetType().Name,message=e.Message}));}}}
